-- first_year_activity
SELECT lower(if(position(repo_name, '/') > 0, substring(repo_name, 1, position(repo_name, '/') - 1), '')) AS login,
  countIf(event_type IN ('PushEvent', 'PullRequestEvent', 'IssuesEvent', 'ReleaseEvent')) AS n_act_12m,
  uniqExactIf(lower(actor_login), event_type = 'PushEvent') AS n_pushers_12m
FROM github_events
